class Solution {
public:
    string minRemoveToMakeValid(string s) {
        int n = s.length();
        int write_idx = 0;
        int balance = 0;

        // Pass 1: remove extra ')'
        for (int i = 0; i < n; i++) {
            char c = s[i];
            if (c == '(') {
                balance++;
                s[write_idx++] = c;
            } else if (c == ')') {
                if (balance > 0) {
                    balance--;
                    s[write_idx++] = c;
                }
            } else {
                s[write_idx++] = c;
            }
        }

        int new_len = write_idx;
        int write_idx2 = new_len - 1;
        balance = 0;

        // Pass 2: remove extra '('
        for (int i = new_len - 1; i >= 0; i--) {
            char c = s[i];
            if (c == ')') {
                balance++;
                s[write_idx2--] = c;
            } else if (c == '(') {
                if (balance > 0) {
                    balance--;
                    s[write_idx2--] = c;
                }
            } else {
                s[write_idx2--] = c;
            }
        }

        return s.substr(write_idx2 + 1, new_len - 1 - write_idx2);
    }
};
